import React, { useState, useRef } from 'react';
import { Download, FileText, Upload, AlertCircle, CheckCircle, Loader2, XCircle, Clock, ClockAlert, Minus, X } from 'lucide-react';
import { useTranslation } from '@/contexts/LanguageContext';

type SheetPrimitive = string | number | boolean | Date | null | undefined;
type SheetRow = SheetPrimitive[];
type SheetData = SheetRow[];

interface ImportedReport {
  id: string;
  fileName: string;
  courseCode: string;
  className: string;
  courseName: string;
  lecturers?: string;
  totalSKS?: string | number;
  classDescData?: SheetData;
  attendanceData?: SheetData;
  meetingSummaryData?: SheetData;
  gradesData?: SheetData;
  gradeWeights?: SheetData;
}

const Reports: React.FC = () => {
  const { t } = useTranslation();
  const [importedReports, setImportedReports] = useState<ImportedReport[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [uploadMessage, setUploadMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [generatingId, setGeneratingId] = useState<string | null>(null);
  const [selectedReport, setSelectedReport] = useState<ImportedReport | null>(null);
  const reportRef = useRef<HTMLDivElement>(null);
  const [isDragActive, setIsDragActive] = useState(false);
  const [isBulkGenerating, setIsBulkGenerating] = useState(false);
  const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0 });

  const getStatusIcon = (status: string) => {
    switch (status?.toLowerCase()) {
      case 'hadir':
      case 'present':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'izin':
      case 'excused':
        return <Clock className="h-4 w-4 text-blue-600" />;
      case 'sakit':
      case 'sick':
        return <AlertCircle className="h-4 w-4 text-yellow-600" />;
      case 'terlambat':
      case 'late':
        return <ClockAlert className="h-4 w-4 text-orange-600" />;
      case 'pengganti':
      case 'substitute':
        return <CheckCircle className="h-4 w-4 text-purple-600" />;
      case 'alpa':
      case 'absent':
        return <XCircle className="h-4 w-4 text-red-600" />;
      default:
        return <Minus className="h-4 w-4 text-gray-300" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status?.toLowerCase()) {
      case 'hadir':
      case 'present':
        return 'bg-green-50 text-green-700';
      case 'izin':
      case 'excused':
        return 'bg-blue-50 text-blue-700';
      case 'sakit':
      case 'sick':
        return 'bg-yellow-50 text-yellow-700';
      case 'terlambat':
      case 'late':
        return 'bg-orange-50 text-orange-700';
      case 'pengganti':
      case 'substitute':
        return 'bg-purple-50 text-purple-700';
      case 'alpa':
      case 'absent':
        return 'bg-red-50 text-red-700';
      default:
        return 'bg-gray-50 text-gray-400';
    }
  };

  // Parse a single XLSX file into an ImportedReport
  const processFile = async (file: File): Promise<ImportedReport> => {
    const XLSX = await import('xlsx');
    const data = await file.arrayBuffer();
    const workbook = XLSX.read(data, { type: 'array' });

    // Read Class Description sheet
    const classDescSheet = workbook.Sheets['Class Description'];
    if (!classDescSheet) {
      throw new Error('Class Description sheet not found');
    }

    const classDescData = XLSX.utils.sheet_to_json<SheetRow>(classDescSheet, { header: 1 }) as SheetData;

    // Extract data from Class Description
    let courseCode = '';
    let className = '';
    let courseName = '';

    const descMap: Record<string, string | number> = {};
    classDescData.forEach((row) => {
      const [key, value] = row;
      if (key === undefined || value === undefined) return;
      const normalizedValue = typeof value === 'number' ? value : String(value);
      descMap[String(key)] = normalizedValue;
    });

    courseCode = (descMap['Course Code'] as string) || 'N/A';
    className = (descMap['Class'] as string) || 'N/A';
    courseName = (descMap['Course Name'] as string) || 'N/A';
    const lecturers = (descMap['Lecturers'] as string) || '';
    const totalSKS = descMap['Total SKS'] || descMap['SKS'] || '';

    // Read Attendance Overview sheet
    const attendanceSheet = workbook.Sheets['Attendance Overview'];
    if (!attendanceSheet) {
      throw new Error('Attendance Overview sheet not found');
    }
    let attendanceSheetData = XLSX.utils.sheet_to_json<SheetRow>(attendanceSheet, { header: 1 }) as SheetData;
    // Filter out empty data rows (keep header)
    const isRowEmpty = (row: SheetRow) => !row || row.every((c) => c === null || c === undefined || String(c).trim() === '');
    if (attendanceSheetData.length > 0) {
      attendanceSheetData = [attendanceSheetData[0], ...attendanceSheetData.slice(1).filter((r) => !isRowEmpty(r))];
    }
    const classDescSheetData: SheetData = classDescData;

    // Read Meeting Summary sheet
    const meetingSheet = workbook.Sheets['Meeting Summary'];
    if (!meetingSheet) {
      throw new Error('Meeting Summary sheet not found');
    }
    let meetingSheetData = XLSX.utils.sheet_to_json<SheetRow>(meetingSheet, { header: 1 }) as SheetData;
    if (meetingSheetData.length > 0) {
      // Keep header, filter empty rows
      meetingSheetData = [meetingSheetData[0], ...meetingSheetData.slice(1).filter((r) => !isRowEmpty(r))];
      // Convert Excel serial date in Date column (index 1) to 'MMM dd, yyyy'
      const formatExcelDate = (val: SheetPrimitive): string => {
        // Already a Date instance
        if (val instanceof Date && !isNaN(val.getTime())) {
          return val.toLocaleDateString('en-US', { month: 'short', day: '2-digit', year: 'numeric' });
        }
        // Numeric serial or numeric-looking string
        const n = typeof val === 'number' ? val : (typeof val === 'string' && /^\d+(\.\d+)?$/.test(val.trim()) ? parseFloat(val) : NaN);
        if (!isNaN(n)) {
          // Excel 1900 date system: days since 1899-12-31, with 1900 leap-year bug; approximate conversion
          const epoch = new Date(Date.UTC(1899, 11, 30)); // 1899-12-30 to account for Excel offset
          const ms = n * 24 * 60 * 60 * 1000;
          const d = new Date(epoch.getTime() + ms);
          return d.toLocaleDateString('en-US', { month: 'short', day: '2-digit', year: 'numeric' });
        }
        // Fallback: return as-is (string or other)
        return typeof val === 'string' ? val : '';
      };
      meetingSheetData = meetingSheetData.map((row, idx) => {
        if (idx === 0) return row; // header
        const newRow = [...row];
        if (newRow[1] !== undefined && newRow[1] !== null && String(newRow[1]).trim() !== '') {
          newRow[1] = formatExcelDate(newRow[1]);
        }
        return newRow;
      });
    }

    // Read Grades Overview sheet (optional - may not exist in older files)
    let gradesSheetData: SheetData | undefined;
    const gradesSheet = workbook.Sheets['Grades Overview'];
    if (gradesSheet) {
      gradesSheetData = XLSX.utils.sheet_to_json<SheetRow>(gradesSheet, { header: 1 }) as SheetData;
      if (gradesSheetData.length > 0) {
        gradesSheetData = [gradesSheetData[0], ...gradesSheetData.slice(1).filter((r) => !isRowEmpty(r))];
      }
    }

    const newReport: ImportedReport = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      fileName: file.name,
      courseCode,
      className,
      courseName,
      lecturers,
      totalSKS,
      classDescData: classDescSheetData,
      attendanceData: attendanceSheetData,
      meetingSummaryData: meetingSheetData,
      gradesData: gradesSheetData,
    };

    return newReport;
  };

  const handleFiles = async (files: FileList | File[]) => {
    const fileArray = Array.from(files || []).filter((f) => /\.xlsx?$/i.test(f.name));
    if (fileArray.length === 0) return;

    setIsProcessing(true);
    setUploadMessage(null);

    const results = await Promise.allSettled(fileArray.map((f) => processFile(f)));
    const successes: ImportedReport[] = [];
    let failures = 0;
    results.forEach((r) => {
      if (r.status === 'fulfilled') successes.push(r.value);
      else failures += 1;
    });

    if (successes.length > 0) {
      setImportedReports((prev) => [...prev, ...successes]);
      const filesText = successes.length === 1 ? '1 file' : `${successes.length} files`;
      const failureText = failures > 0 ? ` (⚠️ ${failures} failed)` : '';
      setUploadMessage({ type: 'success', text: `${filesText} berhasil diimpor${failureText}.` });
    } else {
      setUploadMessage({
        type: 'error',
        text: 'Gagal membaca semua file. Pastikan setiap file memiliki sheet: Class Description, Attendance Overview, Meeting Summary.',
      });
    }

    setIsProcessing(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files && files.length > 0) {
      await handleFiles(files);
    }
    // Reset input
    event.target.value = '';
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (!isDragActive) setIsDragActive(true);
  };

  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(false);
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragActive(false);
    if (e.dataTransfer?.files && e.dataTransfer.files.length > 0) {
      await handleFiles(e.dataTransfer.files);
      e.dataTransfer.clearData();
    }
  };

  const handleViewReport = (report: ImportedReport) => {
    setSelectedReport(report);
  };

  const handleCloseReport = () => {
    setSelectedReport(null);
  };

  const generatePDFForReport = async (report: ImportedReport, element: HTMLElement): Promise<boolean> => {
    try {
      const [{ default: html2canvas }, { default: jsPDF }] = await Promise.all([
        import('html2canvas-pro'),
        import('jspdf')
      ]);

      const canvas = await html2canvas(element, {
        scale: 1.5, // Reduced from 2 to 1.5 for smaller file size while maintaining quality
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff',
      });

      const imgWidth = 210;
      const pageHeight = 297;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;

      const pdf = new jsPDF('p', 'mm', 'a4');
      let position = 0;

      // Convert canvas to JPEG with compression for smaller file size
      const imgData = canvas.toDataURL('image/jpeg', 0.85); // JPEG with 85% quality

      pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      while (heightLeft > 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      const filename = `Class_Summary_${report.className}_${report.courseName.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`;
      pdf.save(filename);
      return true;
    } catch (error) {
      return false;
    }
  };

  const handleGeneratePDF = async () => {
    if (!reportRef.current) return;

    setGeneratingId('pdf-generation');

    try {
      await generatePDFForReport(selectedReport!, reportRef.current);
    } catch (error) {
      alert('Failed to generate PDF. Please try again.');
    } finally {
      setGeneratingId(null);
    }
  };

  const handleBulkGeneratePDF = async () => {
    if (importedReports.length === 0) return;

    setIsBulkGenerating(true);
    setBulkProgress({ current: 0, total: importedReports.length });

    let successCount = 0;
    let failCount = 0;

    for (let i = 0; i < importedReports.length; i++) {
      const report = importedReports[i];
      setBulkProgress({ current: i + 1, total: importedReports.length });

      // Temporarily set the report as selected to render it
      setSelectedReport(report);
      
      // Wait for DOM to update
      await new Promise(resolve => setTimeout(resolve, 100));

      if (reportRef.current) {
        const success = await generatePDFForReport(report, reportRef.current);
        if (success) {
          successCount++;
        } else {
          failCount++;
        }
        
        // Small delay between generations to prevent browser freezing
        await new Promise(resolve => setTimeout(resolve, 300));
      }
    }

    // Clear selected report and show completion message
    setSelectedReport(null);
    setIsBulkGenerating(false);
    setBulkProgress({ current: 0, total: 0 });

    const message = failCount > 0 
      ? `Bulk generation complete: ${successCount} succeeded, ${failCount} failed`
      : `Successfully generated ${successCount} PDF reports!`;
    
    setUploadMessage({ 
      type: failCount > 0 ? 'error' : 'success', 
      text: message 
    });
  };

  const handleDeleteReport = (id: string) => {
    setImportedReports((prev) => prev.filter((r) => r.id !== id));
  };

  // If a report is selected, show the report view
  if (selectedReport) {
    // Get meeting headers (P1, P2, etc.) from attendance data
    const meetingHeaders: string[] = selectedReport.attendanceData && selectedReport.attendanceData.length > 0
      ? selectedReport.attendanceData[0].slice(2).map((h) => String(h))
      : [];

    // Build a map of meeting -> date from meeting summary data
    const meetingDateMap: Record<string, string> = {};
    if (selectedReport.meetingSummaryData && selectedReport.meetingSummaryData.length > 1) {
      selectedReport.meetingSummaryData.slice(1).forEach((row) => {
        const meeting = row[0];
        const date = row[1];
        if (meeting !== undefined && meeting !== null && date !== undefined && date !== null) {
          meetingDateMap[String(meeting)] = String(date);
        }
      });
    }

    return (
      <div className="p-6 space-y-6">
        {/* Action Bar */}
        <div className="flex justify-between items-center">
          <button
            onClick={handleCloseReport}
            className="btn-secondary flex items-center gap-2"
          >
            <X className="h-4 w-4" />
            <span>Close Report</span>
          </button>

          <button
            onClick={handleGeneratePDF}
            disabled={generatingId === 'pdf-generation'}
            className="btn-primary flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:cursor-pointer transition-all active:scale-95"
          >
            {generatingId === 'pdf-generation' ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                <span>Generating PDF...</span>
              </>
            ) : (
              <>
                <Download className="h-4 w-4" />
                <span>Generate PDF Report</span>
              </>
            )}
          </button>
        </div>

        {/* Report Content */}
        <div ref={reportRef} className="bg-white rounded-lg shadow-sm border border-gray-200">
          {/* Header */}
          <div className="px-6 pt-6 pb-3">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Class Summary</h1>
              <p className="text-base text-gray-600 mt-1">
                {selectedReport.courseCode && <span className="font-medium">{selectedReport.courseCode}</span>}
                {selectedReport.courseCode && ' - '}
                {selectedReport.courseName} - Class {selectedReport.className}
                {selectedReport.totalSKS && ` (${selectedReport.totalSKS} SKS)`}
              </p>
              {selectedReport.lecturers && (
                <p className="text-sm text-gray-500 mt-2">
                  {selectedReport.lecturers}
                </p>
              )}
            </div>
          </div>

          {/* Content */}
          <div>
            {/* Attendance Table Section */}
            <div className="px-6 py-3">
              <h3 className="text-lg font-semibold text-gray-900 mb-4">Attendance Overview</h3>
              <div className="border border-gray-300 rounded-lg overflow-hidden">
                <div className="overflow-x-auto">
                  <div className="flex gap-0">
                    {/* Fixed NIM/Name Table */}
                    <div className="flex-shrink-0 sticky left-0 z-10">
                      <table className="border-collapse">
                        <thead>
                          <tr className="bg-gray-50">
                            <th className="bg-gray-50 border-r border-b border-gray-300 px-2 py-2 text-left text-xs font-semibold text-gray-700 w-24 h-14">
                              NIM
                            </th>
                            <th className="bg-gray-50 border-r border-b border-gray-300 px-2 py-2 text-left text-xs font-semibold text-gray-700 w-52 h-14">
                              Name
                            </th>
                          </tr>
                        </thead>
                        <tbody>
                          {selectedReport.attendanceData?.slice(1).map((row, index) => (
                            <tr key={index} className="hover:bg-gray-50 h-9">
                              <td className="bg-white border-r border-b border-gray-300 px-2 py-1.5 text-xs font-medium text-gray-900">
                                {row[0] ? String(row[0]) : '-'}
                              </td>
                              <td className="bg-white border-r border-b border-gray-300 px-2 py-1.5 text-xs text-gray-900 truncate">
                                {row[1] ? String(row[1]) : '-'}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>

                    {/* Scrollable Meetings Table */}
                    <div className="flex-1">
                      <table className="border-collapse">
                        <thead>
                          <tr className="bg-gray-50">
                            {meetingHeaders.map((header, index) => (
                              <th
                                key={index}
                                className="border-r border-b border-gray-300 px-1 py-2 text-center text-xs font-semibold text-gray-700 w-16 h-14"
                              >
                                <div className="flex flex-col items-center gap-0.5">
                                  <span className="font-bold text-[10px]">{String(header)}</span>
                                  {meetingDateMap[header] && (
                                    <span className="text-gray-500 font-normal text-[9px]">
                                      {meetingDateMap[header]}
                                    </span>
                                  )}
                                </div>
                              </th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {selectedReport.attendanceData?.slice(1).map((row, rowIndex) => (
                            <tr key={rowIndex} className="hover:bg-gray-50 h-9">
                              {row.slice(2).map((status, colIndex) => {
                                const statusValue = status === null || status === undefined ? '' : String(status);
                                return (
                                <td
                                    key={colIndex}
                                    className={`border-r border-b border-gray-300 px-1 py-1.5 text-center ${getStatusColor(statusValue)}`}
                                  >
                                    <span className="inline-flex items-center gap-1 justify-center">
                                      {getStatusIcon(statusValue)}
                                      <span className="text-[10px] text-gray-700">{statusValue}</span>
                                    </span>
                                  </td>
                                );
                              })}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Legend */}
            <div className="px-6 py-3">
              <div className="flex items-center gap-4 text-xs flex-wrap">
                <span className="font-medium text-gray-700">Legend:</span>
                <div className="flex items-center gap-1">
                  <CheckCircle className="h-4 w-4 text-green-600" />
                  <span className="text-gray-600">Present</span>
                </div>
                <div className="flex items-center gap-1">
                  <ClockAlert className="h-4 w-4 text-orange-600" />
                  <span className="text-gray-600">Late</span>
                </div>
                <div className="flex items-center gap-1">
                  <Clock className="h-4 w-4 text-blue-600" />
                  <span className="text-gray-600">Excused</span>
                </div>
                <div className="flex items-center gap-1">
                  <AlertCircle className="h-4 w-4 text-yellow-600" />
                  <span className="text-gray-600">Sick</span>
                </div>
                <div className="flex items-center gap-1">
                  <XCircle className="h-4 w-4 text-red-600" />
                  <span className="text-gray-600">Absent</span>
                </div>
                <div className="flex items-center gap-1">
                  <CheckCircle className="h-4 w-4 text-purple-600" />
                  <span className="text-gray-600">Substitute</span>
                </div>
                <div className="flex items-center gap-1">
                  <Minus className="h-4 w-4 text-gray-300" />
                  <span className="text-gray-600">No data</span>
                </div>
              </div>
            </div>

            {/* Meeting Descriptions Table */}
            <div className="px-6 py-3">
              <h3 className="text-lg font-semibold text-gray-900 mb-4">Meeting Descriptions</h3>
              <div className="border border-gray-300 rounded-lg overflow-hidden">
                <table className="w-full border-collapse text-xs">
                  <thead>
                    <tr className="bg-gray-50">
                      <th className="border-b border-gray-300 px-3 py-2 text-left font-semibold text-gray-700 w-16">
                        Meeting
                      </th>
                      <th className="border-b border-gray-300 px-3 py-2 text-left font-semibold text-gray-700 w-28">
                        Date
                      </th>
                      <th className="border-b border-gray-300 px-3 py-2 text-left font-semibold text-gray-700">
                        Topic
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {selectedReport.meetingSummaryData?.slice(1).map((row, index) => (
                      <tr key={index} className="hover:bg-gray-50">
                        <td className="border-b border-gray-300 px-3 py-2 font-medium text-gray-900">
                          {row[0] ? String(row[0]) : '-'}
                        </td>
                        <td className="border-b border-gray-300 px-3 py-2 text-gray-600">
                          {row[1] ? String(row[1]) : '-'}
                        </td>
                        <td className="border-b border-gray-300 px-3 py-2 text-gray-600">
                          {row[2] ? String(row[2]) : '-'}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Grades Overview Table */}
            {selectedReport.gradesData && selectedReport.gradesData.length > 0 && (
              <div className="px-6 py-3 pb-6">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Grades Overview</h3>
                <div className="border border-gray-300 rounded-lg overflow-hidden">
                  <div className="overflow-x-auto">
                    <table className="w-full border-collapse text-xs">
                      <thead>
                        <tr className="bg-gray-50">
                              {selectedReport.gradesData[0].map((header, index) => (
                            <th
                              key={index}
                              className={`border-${index < selectedReport.gradesData![0].length - 1 ? 'r' : ''} border-b border-gray-300 px-3 py-2 ${
                                index <= 1 ? 'text-left' : 'text-center'
                              } font-semibold text-gray-700`}
                            >
                              {String(header)}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {selectedReport.gradesData.slice(1).map((row, rowIndex) => {
                          // Check if this is the weights row (last row or contains "Component Weights")
                          const isWeightsRow = rowIndex === selectedReport.gradesData!.length - 2 || 
                                              (row[0] && String(row[0]).toLowerCase().includes('weight'));
                          
                          if (isWeightsRow) {
                            // Special rendering for weights row
                            return (
                              <tr key={rowIndex} className="bg-blue-50 font-bold">
                                {/* Component Weights label - spans first 2 columns */}
                                <td 
                                  colSpan={2} 
                                  className="border-r border-b border-gray-300 px-3 py-2 text-left text-gray-900"
                                >
                                  {row[0] === null || row[0] === undefined ? '-' : String(row[0])}
                                </td>
                                {/* Individual weight percentages - columns 2-7 */}
                                {row.slice(2, 8).map((cell, idx) => (
                                  <td 
                                    key={idx + 2}
                                    className="border-r border-b border-gray-300 px-3 py-2 text-center text-blue-600"
                                  >
                                    {cell === null || cell === undefined ? '-' : String(cell)}
                                  </td>
                                ))}
                                {/* Total: 100% - spans last 3 columns */}
                                <td 
                                  colSpan={3}
                                  className="border-b border-gray-300 px-3 py-2 text-center text-blue-600"
                                >
                                  {row[8] === null || row[8] === undefined ? '-' : String(row[8])}
                                </td>
                              </tr>
                            );
                          }
                          
                          // Regular student row
                          return (
                            <tr key={rowIndex} className="hover:bg-gray-50">
                              {row.map((cell, cellIndex) => {
                                // Determine styling based on column
                                const isNIM = cellIndex === 0;
                                const isName = cellIndex === 1;
                                const isLetterGrade = cellIndex === selectedReport.gradesData![0].length - 2;
                                const isFinalGrade = cellIndex >= selectedReport.gradesData![0].length - 3;
                                
                                return (
                                  <td
                                    key={cellIndex}
                                    className={`border-${cellIndex < row.length - 1 ? 'r' : ''} border-b border-gray-300 px-3 py-2 ${
                                      cellIndex <= 1 ? 'text-left' : 'text-center'
                                    } ${
                                      isNIM
                                        ? 'font-medium text-gray-900'
                                        : isName
                                        ? 'text-gray-900'
                                        : isLetterGrade
                                        ? 'font-bold text-blue-600'
                                        : isFinalGrade
                                        ? 'font-semibold text-gray-900'
                                        : 'text-gray-600'
                                    }`}
                                  >
                                    {cell === null || cell === undefined ? '-' : String(cell)}
                                  </td>
                                );
                              })}
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <FileText className="h-8 w-8 text-blue-600" />
          <div>
            <h1 className="text-2xl font-bold text-gray-900">{t('adminReports.title')}</h1>
            <p className="text-gray-600">{t('adminReports.subtitle')}</p>
          </div>
        </div>
      </div>

      {/* Upload Section */}
      <div className="card p-6">
        <div className="space-y-4">
          <h2 className="text-lg font-semibold text-gray-900">{t('adminReports.uploadTitle')}</h2>
          
          <div
            className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
              isDragActive ? 'border-blue-500 bg-blue-50' : 'border-blue-300 hover:border-blue-400'
            }`}
            onDragOver={handleDragOver}
            onDragEnter={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
          >
            <input
              type="file"
              accept=".xlsx,.xls"
              multiple
              onChange={handleFileUpload}
              disabled={isProcessing}
              className="hidden"
              id="file-upload"
            />
            <label htmlFor="file-upload" className="cursor-pointer">
              <div className="flex flex-col items-center justify-center">
                <Upload className="h-12 w-12 text-blue-400 mb-3" />
                <p className="text-lg font-medium text-gray-900">{t('adminReports.dragDrop')}</p>
                <p className="text-sm text-gray-500 mt-2">{t('adminReports.orClick')}</p>
                <p className="text-xs text-gray-400 mt-3">
                  {t('adminReports.fileRequirements')}
                </p>
                {isProcessing && (
                  <div className="flex items-center gap-2 mt-4 text-blue-600">
                    <Loader2 className="h-4 w-4 animate-spin" />
                    <span className="text-sm">{t('adminReports.processing')}</span>
                  </div>
                )}
              </div>
            </label>
          </div>

          {uploadMessage && (
            <div
              className={`flex items-center gap-3 p-4 rounded-lg ${
                uploadMessage.type === 'success'
                  ? 'bg-green-50 text-green-700 border border-green-200'
                  : 'bg-red-50 text-red-700 border border-red-200'
              }`}
            >
              {uploadMessage.type === 'success' ? (
                <CheckCircle className="h-5 w-5 flex-shrink-0" />
              ) : (
                <AlertCircle className="h-5 w-5 flex-shrink-0" />
              )}
              <span className="text-sm">{uploadMessage.text}</span>
            </div>
          )}
        </div>
      </div>

      {/* Imported Reports List */}
      {importedReports.length > 0 ? (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold text-gray-900">{t('adminReports.importedReports')} ({importedReports.length})</h2>
            <div className="flex gap-2">
              <button
                onClick={handleBulkGeneratePDF}
                disabled={isBulkGenerating || isProcessing}
                className="btn-primary flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:cursor-pointer transition-all active:scale-95"
              >
                {isBulkGenerating ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    <span>{t('adminReports.generating')} {bulkProgress.current}/{bulkProgress.total}...</span>
                  </>
                ) : (
                  <>
                    <Download className="h-4 w-4" />
                    <span>{t('adminReports.bulkGenerate')}</span>
                  </>
                )}
              </button>
              <button
                onClick={() => setImportedReports([])}
                disabled={isBulkGenerating || isProcessing || importedReports.length === 0}
                className="btn-secondary flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hover:cursor-pointer transition-all active:scale-95"
              >
                <X className="h-4 w-4" />
                <span>{t('adminReports.removeAll')}</span>
              </button>
            </div>
          </div>
          
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {importedReports.map((report) => (
              <div key={report.id} className="card p-6">
                <div className="space-y-4">
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900 mb-1">
                      {report.courseCode && <span className="text-blue-600">{report.courseCode}</span>}
                      {report.courseCode && ' - '}
                      {report.courseName} - Class {report.className}
                    </h3>
                    <p className="text-sm text-gray-500">{t('adminReports.file')}: {report.fileName}</p>
                  </div>

                  <div className="flex space-x-2">
                    <button
                      onClick={() => handleViewReport(report)}
                      className="flex-1 btn-primary flex items-center justify-center space-x-2"
                    >
                      <FileText className="h-4 w-4" />
                      <span>{t('adminReports.viewReport')}</span>
                    </button>
                    <button
                      onClick={() => handleDeleteReport(report.id)}
                      className="flex-1 btn-secondary flex items-center justify-center space-x-2"
                    >
                      <span>{t('adminReports.remove')}</span>
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="text-center py-12 card p-6">
          <FileText className="mx-auto h-12 w-12 text-gray-400 mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">{t('adminReports.noReports')}</h3>
          <p className="text-gray-500 mb-6">{t('adminReports.uploadPrompt')}</p>
        </div>
      )}
    </div>
  );
};

export default Reports;